$_MODULE['<{priceandorder}prestashop>_settings_959506ad82cfabe6a4c4e5b871e64a44'] = 'Nützlich, da der Seitenleisten-Block auf kleinen Bildschirmen oft ausgeblendet ist; die schwebende Schaltfläche funktioniert auch auf Mobilgeräten.';
$_MODULE['<{priceandorder}prestashop>_settings_9bbe38ded96b1cd34086972a0d2b7956'] = 'Die Produktbeschreibung wird immer abgefragt. E-Mail wird bei Gästen immer abgefragt; angemeldete Kunden sehen sie nie, ihre Konto-E-Mail wird automatisch verwendet.';
