$_MODULE['<{priceandorder}prestashop>_tutorial_0335b6ca536d6d636bdf088442b44790'] = 'Prüfen Sie die Empfängeradresse in den Einstellungen auf Tippfehler, schauen Sie in Ihren Spam-Ordner und stellen Sie sicher, dass ausgehende E-Mails grundsätzlich funktionieren, indem Sie ein anderes Modul oder Erweiterte Parameter > E-Mail testen. Jede Anfrage wird unabhängig davon im Tab Angebotsanfragen gespeichert, sodass Sie sie dort immer finden.';
$_MODULE['<{priceandorder}prestashop>_tutorial_0431a668e8d90860362093b461947781'] = 'Senden Sie eine Testanfrage über Ihren Shop und prüfen Sie, ob sie im Tab Angebotsanfragen und in Ihrem Postfach ankommt.';
$_MODULE['<{priceandorder}prestashop>_tutorial_106e29c08b607e3b79c61dc35b0289a7'] = 'Ich erhalte keine E-Mails zu Angebotsanfragen.';
$_MODULE['<{priceandorder}prestashop>_tutorial_231cf4c70d866b616c21baddaeed0696'] = 'Fehlerbehebung';
$_MODULE['<{priceandorder}prestashop>_tutorial_46ec8e9cec078e1824c2285289a9845a'] = 'Das liegt fast immer am automatischen Spam-Schutz: Formular schneller als 3 Sekunden nach dem Laden der Seite absenden, mehr als eine Stunde nach dem Laden absenden oder mehr als 5 Anfragen in einer Stunde von derselben Verbindung. Bitten Sie sie, die Seite neu zu laden und es erneut zu versuchen.';
$_MODULE['<{priceandorder}prestashop>_tutorial_487e540af0ce1574b40b98daaf9a704e'] = 'Ein Besucher sagt, das Formular habe seine Übermittlung abgelehnt.';
$_MODULE['<{priceandorder}prestashop>_tutorial_6d08bb064fa0dc50df631711d8f9a10a'] = 'Die Dashboard-Benachrichtigungskarte wird nicht angezeigt.';
$_MODULE['<{priceandorder}prestashop>_tutorial_738cfeba525f1715b35cdbae92e826d9'] = 'Mein Werbebild wirkt gestreckt oder wird abgelehnt.';
$_MODULE['<{priceandorder}prestashop>_tutorial_775956a2316b82459c84f10d788864d5'] = 'Brauchen Sie mehr Hilfe? Kontakt';
$_MODULE['<{priceandorder}prestashop>_tutorial_7f1b3b7557f81bb527614a601f1df990'] = 'Wählen Sie, welche optionalen Felder Besucher ausfüllen sollen (Adresse, Telefon, Menge...).';
$_MODULE['<{priceandorder}prestashop>_tutorial_813ce2687d65c0253de66d80cddab8f3'] = 'Der Seitenleisten-Block und die schwebende Schaltfläche teilen sich dasselbe Formular; ein Besucher kann beides nutzen.';
$_MODULE['<{priceandorder}prestashop>_tutorial_958aae0a194da728c36d3e7221675a84'] = 'Das Formular erscheint nicht im Shop.';
$_MODULE['<{priceandorder}prestashop>_tutorial_9ffdb95250e26c7a6b468126ac7c75b0'] = 'So funktioniert es';
$_MODULE['<{priceandorder}prestashop>_tutorial_a7821d5fcb146c5ad0b90884e504d314'] = 'Uploads sind auf JPG-, PNG-, GIF- oder WEBP-Dateien bis 4 MB beschränkt und werden automatisch auf maximal 400x280 px skaliert, wobei die Proportionen erhalten bleiben, sodass die Datei selbst nie verzerrt wird.';
$_MODULE['<{priceandorder}prestashop>_tutorial_bc9e9fef06497c843ddb85f457c24635'] = 'Angemeldete Kunden werden nie nach Name oder E-Mail gefragt &mdash; ihre Kontodaten werden automatisch verwendet.';
$_MODULE['<{priceandorder}prestashop>_tutorial_bd4b0999a932632905b77cd2fbc0a97c'] = 'Spam-Schutz ist automatisch: ein verstecktes Fallenfeld und eine kurze Verzögerungsprüfung blockieren automatisierte Übermittlungen still, und es werden höchstens 5 Anfragen pro Stunde vom selben Besucher akzeptiert. Echte Besucher müssen nichts lösen.';
$_MODULE['<{priceandorder}prestashop>_tutorial_cb59b87e00d11222bfd9159d0d23836f'] = 'Erste Schritte';
$_MODULE['<{priceandorder}prestashop>_tutorial_e41d93a6e7c1aa5aab80cb4cab9dc886'] = 'Auf Ihrem Dashboard erscheint eine Benachrichtigungskarte, sobald neue Anfragen vorliegen, mit einem direkten Link zu diesem Tab Angebotsanfragen. Sie verschwindet, sobald jede neue Anfrage als bearbeitet markiert oder gelöscht wurde.';
$_MODULE['<{priceandorder}prestashop>_tutorial_ea67abf8988cbc6b378a032f822801f8'] = 'Öffnen Sie den Tab Einstellungen und geben Sie die E-Mail-Adresse(n) ein, die Angebotsanfragen erhalten sollen.';
$_MODULE['<{priceandorder}prestashop>_tutorial_f9459c8296e5294ec5990a767724198b'] = 'Die Links zu AGB / Datenschutzerklärung fehlen oder sind falsch.';
$_MODULE['<{priceandorder}prestashop>_tutorial_fe920a7d738e80a23e8675183ec4450d'] = 'Jede Übermittlung wird im Tab Angebotsanfragen gespeichert, auch wenn die Benachrichtigungs-E-Mail nicht zugestellt wird, sodass nichts verloren geht.';
