$_MODULE['<{priceandorder}prestashop>priceandorder_4d001e13295999e5cd7d1bfeb08ce238'] = 'Dadurch werden Ihre Einstellungen und alle erhaltenen Angebotsanfragen dauerhaft gelöscht. Sind Sie sicher?';
$_MODULE['<{priceandorder}prestashop>priceandorder_5a2932284040389d13d1f7c64a2d69cc'] = 'Die Empfänger-E-Mail-Adresse für Angebotsanfragen ist erforderlich.';
